CREATE TABLE IF NOT EXISTS rooms(id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL, room_type TEXT NOT NULL, floor INTEGER NOT NULL DEFAULT 1, active BOOLEAN NOT NULL DEFAULT TRUE, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS guests(id TEXT PRIMARY KEY, first_name TEXT NOT NULL DEFAULT '', last_name TEXT NOT NULL DEFAULT '', phone TEXT DEFAULT '', email TEXT DEFAULT '', notes TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS reservations(id TEXT PRIMARY KEY, room_id TEXT REFERENCES rooms(id), guest_id TEXT REFERENCES guests(id), arrival DATE NOT NULL, departure DATE NOT NULL, adults INTEGER NOT NULL DEFAULT 2, children INTEGER NOT NULL DEFAULT 0, rate NUMERIC(12,2) NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'confirmed', payment_status TEXT NOT NULL DEFAULT 'unpaid', channel TEXT DEFAULT 'Manual', notes TEXT DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS folios(id TEXT PRIMARY KEY, reservation_id TEXT REFERENCES reservations(id), room_id TEXT REFERENCES rooms(id), status TEXT NOT NULL DEFAULT 'open', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS folio_items(id TEXT PRIMARY KEY, folio_id TEXT REFERENCES folios(id) ON DELETE CASCADE, category TEXT NOT NULL, description TEXT NOT NULL, quantity NUMERIC(10,2) NOT NULL DEFAULT 1, unit_price NUMERIC(12,2) NOT NULL DEFAULT 0, source TEXT DEFAULT 'PMS', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY, reservation_id TEXT REFERENCES reservations(id), folio_id TEXT REFERENCES folios(id), amount NUMERIC(12,2) NOT NULL, method TEXT NOT NULL, reference TEXT DEFAULT '', paid_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS restaurant_zones(id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS restaurant_tables(id TEXT PRIMARY KEY, zone_id TEXT REFERENCES restaurant_zones(id) ON DELETE CASCADE, name TEXT NOT NULL, seats INTEGER NOT NULL DEFAULT 4, x INTEGER NOT NULL DEFAULT 20, y INTEGER NOT NULL DEFAULT 20, status TEXT NOT NULL DEFAULT 'available');
CREATE TABLE IF NOT EXISTS menu_items(id TEXT PRIMARY KEY, category TEXT NOT NULL, name TEXT NOT NULL, price NUMERIC(12,2) NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS restaurant_orders(id TEXT PRIMARY KEY, table_id TEXT REFERENCES restaurant_tables(id), room_id TEXT REFERENCES rooms(id), reservation_id TEXT REFERENCES reservations(id), guest_name TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'open', payment_method TEXT DEFAULT '', total NUMERIC(12,2) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS restaurant_order_items(id TEXT PRIMARY KEY, order_id TEXT REFERENCES restaurant_orders(id) ON DELETE CASCADE, menu_item_id TEXT REFERENCES menu_items(id), name TEXT NOT NULL, quantity NUMERIC(10,2) NOT NULL, unit_price NUMERIC(12,2) NOT NULL);
